import { type FormEvent, useState } from "react";
import { Button, LinkButton, TextField } from "../../../design-system/components";
import "./AuthenticatorSetup.css";

export interface PendingEnrolment {
  enrolmentId: string;
  /** Base64 PNG of the QR code, generated by Keycloak (no QR library in the app). */
  qrCode: string;
  /** The same secret as text, for people who can't scan. */
  secret: string;
}

export interface AuthenticatorSetupProps {
  enrolment: PendingEnrolment;
  busy: boolean;
  onConfirm: (code: string) => void;
  onCancel: () => void;
}

/**
 * MFA-ENROL: the in-app "set up your authenticator" step of the sign-in screen. Shown after the
 * password was accepted for a two-step role with no authenticator yet. The secret stays in
 * Keycloak; this screen only displays it once so the user can scan or type it.
 */
export function AuthenticatorSetup({ enrolment, busy, onConfirm, onCancel }: AuthenticatorSetupProps) {
  const [code, setCode] = useState("");
  const [codeError, setCodeError] = useState("");
  const [copied, setCopied] = useState(false);

  const submit = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!/^[0-9]{6}$/.test(code)) {
      setCodeError("Enter the 6-digit code shown in your authenticator app.");
      return;
    }
    setCodeError("");
    onConfirm(code);
    setCode("");
  };

  const copySecret = async () => {
    try {
      await navigator.clipboard.writeText(enrolment.secret.replace(/\s+/g, ""));
      setCopied(true);
    } catch {
      setCopied(false);
    }
  };

  return (
    <div className="mfa-setup">
      <ol className="mfa-setup__steps">
        <li>
          Install an authenticator app on your phone, such as <strong>Google Authenticator</strong>,{" "}
          <strong>Microsoft Authenticator</strong> or <strong>Authy</strong>.
        </li>
        <li>In the app, add an account and scan this code.</li>
      </ol>

      <div className="mfa-setup__qr-row">
        <img
          className="mfa-setup__qr"
          src={`data:image/png;base64,${enrolment.qrCode}`}
          alt="QR code to add EDU 360 to your authenticator app"
          width={168}
          height={168}
        />
        <div className="mfa-setup__manual">
          <span className="mfa-setup__manual-label">Can't scan? Enter this key instead:</span>
          <code className="mfa-setup__secret" aria-label="Set-up key">
            {enrolment.secret}
          </code>
          <LinkButton onClick={() => void copySecret()}>{copied ? "Copied" : "Copy key"}</LinkButton>
        </div>
      </div>

      <form onSubmit={submit} noValidate>
        <TextField
          id="mfa-setup-code"
          label="3. Enter the 6-digit code from the app"
          inputMode="numeric"
          autoComplete="one-time-code"
          maxLength={6}
          value={code}
          onChange={(e) => {
            setCode(e.target.value.replace(/\D/g, ""));
            setCodeError("");
          }}
          placeholder="6-digit code"
          aria-invalid={codeError ? true : undefined}
          aria-describedby={codeError ? "mfa-setup-code-error" : undefined}
          required
          autoFocus
        />
        {codeError && (
          <p id="mfa-setup-code-error" className="mfa-setup__field-error" role="alert">
            {codeError}
          </p>
        )}
        <Button type="submit" size="lg" block busy={busy} className="auth-submit">
          {busy ? "Checking…" : "Confirm and continue"}
        </Button>
      </form>
      <div className="mfa-setup__cancel">
        <LinkButton onClick={onCancel}>Back to sign-in</LinkButton>
      </div>
    </div>
  );
}
